private void button1_Click(object sender, EventArgs e)
{
    double mas, h, imt = 0;
    h = System.Convert.ToDouble(textBox1.Text);
    mas = System.Convert.ToDouble(textBox2.Text);
    if ((mas < 0 || mas > 200) || (h < 0 || h > 200))
        label4.Text = "Неверный ввод данных";
    else
    {
        imt = mas / (h * h);
        label4.Text = imt.ToString("0.##");
        if (radioButton3.Checked == true && radioButton4.Checked == false) // мужской пол
        {
            if ((imt > 18.4) && (imt < 23.9)) label5.Text = "Норма";
            else if (imt < 18.5) label5.Text = "Ниже нормы";
            else label5.Text = "Выше нормы";
        }
        if (radioButton3.Checked == false && radioButton4.Checked == true) // женский пол
        {
            if ((imt > 20) && (imt < 25)) label5.Text = "Норма";
            else if (imt < 20.1) label5.Text = "Ниже нормы";
            else label5.Text = "Выше нормы";
        }
    }
}

